	@ParameterizedTest(name = "foreignBeforeRecovery={0}")
	@ValueSource(booleans = { false, true })
	void actualNativeWriterCannotInvalidateTheRetirementLivenessProof(boolean foreignBeforeRecovery,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CompletableFuture<Throwable> outcome = new CompletableFuture<>();
		Thread recovery = null;
		Process foreign = null;
		ProbeValues values = null;
		boolean nativeSettled = false;
		Throwable primaryFailure = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin(org.eclipse.rdf4j.common.transaction.IsolationLevels.NONE);
				connection.setNamespace("seed", "urn:retirement-foreign:seed:");
				connection.commit();
			}
			values = store.values.get();
			assertNotNull(values);
			var orphan = SimpleValueFactory.getInstance().createIRI("urn:retirement-foreign:orphan");
			values.startTransaction(true);
			long id = values.storeValue(orphan);
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			byte[] before = values.getData(id).clone();
			Files.write(directory.resolve("orphan-before.bin"), before);
			LmdbSailStore backing = store.getBackingStore();
			assertTrue(backing.hasRetiredValueIds());
			values.evidence = directory;
			values.pauseAfterLiveness = !foreignBeforeRecovery;
			values.failAfterRetirementCommit.set(!foreignBeforeRecovery);
			values.armed.set(true);
			if (foreignBeforeRecovery) {
				foreign = startForeignWriter(directory);
				assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
				assertTrue(foreign.exitValue() == 0 && Files.exists(directory.resolve("foreign-committed")),
						"the pre-existing foreign commit must actually succeed");
			}
			ProbeValues activeValues = values;
			recovery = Thread.ofPlatform().name("native-fenced-retirement").unstarted(() -> {
				activeValues.recoveryOwner = Thread.currentThread();
				try {
					backing.recoverRetiredValueIds();
					outcome.complete(null);
				} catch (Throwable failure) {
					outcome.complete(failure);
				}
			});
			recovery.start();
			boolean ownedFenceAtLiveness = false;
			if (!foreignBeforeRecovery) {
				assertTrue(values.livenessComplete.await(10, TimeUnit.SECONDS),
						"the actual final liveness checker must finish before the foreign attempt");
				ownedFenceAtLiveness = backing.getTripleStore().currentWriterTransaction() != null;
				foreign = startForeignWriter(directory);
				assertTrue(awaitFile(directory.resolve("foreign-attempt"), foreign),
						"the independent process must reach native writer admission");
				if (!ownedFenceAtLiveness) {
					// Diagnostic for the pre-fix path: retain a real commit in the exposed window. This does not
					// weaken the fence assertion below; the protected path lets the native writer finish only later.
					assertTrue(foreign.waitFor(10, TimeUnit.SECONDS));
					assertTrue(Files.exists(directory.resolve("foreign-committed")));
				}
				values.releaseLiveness.countDown();
			}
			Throwable failure = outcome.get(20, TimeUnit.SECONDS);
			assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
			assertTrue(foreign.exitValue() == 0, "foreign writer output: " + directory.resolve("foreign.log"));
			assertNull(values.currentWriterTransaction());
			assertNull(backing.getTripleStore().currentWriterTransaction());
			nativeSettled = true;
			if (foreignBeforeRecovery) {
				byte[] after = values.getData(id);
				assertAll(
						() -> assertNotNull(failure, "an unowned native generation must fail before reclamation"),
						() -> assertArrayEquals(before, after, "the original dictionary payload must survive"),
						() -> assertTrue(backing.hasRetiredValueIds(), "the durable candidate must remain retryable"),
						() -> assertFalse(Files.exists(directory.resolve("dictionary-committed"))));
			} else {
				boolean owned = ownedFenceAtLiveness;
				assertAll(
						() -> assertTrue(owned, "full liveness must own a real TripleStore writer fence"),
						() -> assertSame(activeValues.retirementCommitFailure.get(), failure,
								"the first committed batch must retain the injected cleanup failure"),
						() -> assertTrue(Files.exists(directory.resolve("dictionary-committed"))),
						() -> assertFalse(Files.exists(directory.resolve("foreign-before-dictionary")),
								"a native foreign commit must not fit between final liveness and dictionary commit"),
						() -> assertEquals(LmdbValue.UNKNOWN_ID, activeValues.getId(orphan),
								"the original orphan alias must be retired"),
						() -> {
							var frontier = activeValues.pollRetiredIds(Long.MAX_VALUE, 64);
							assertNotNull(frontier, "the orphan's recursive namespace frontier must be durable");
							assertFalse(frontier.ids.contains(id), "the original retirement record must be removed");
							assertFalse(frontier.ids.isEmpty(),
									"recursive child work remains for the next bounded batch");
						});
			}
		} catch (Exception | Error failure) {
			primaryFailure = failure;
			throw failure;
		} finally {
			try {
				if (values != null) {
					values.releaseLiveness.countDown();
				}
				if (recovery != null) {
					recovery.join(TimeUnit.SECONDS.toMillis(20));
				}
				if (foreign != null && foreign.isAlive()) {
					// The child may still be waiting for the actual fence. Never terminate an admitted native owner.
					foreign.waitFor(20, TimeUnit.SECONDS);
				}
				LmdbSailStore backing = store.getBackingStore();
				nativeSettled = (recovery == null || !recovery.isAlive()) && (foreign == null || !foreign.isAlive())
						&& (backing == null || backing.valueStore().currentWriterTransaction() == null
								&& backing.getTripleStore().currentWriterTransaction() == null);
				if (nativeSettled) {
					try {
						repository.shutDown();
					} catch (RuntimeException closeFailure) {
						// A deliberately foreign generation may fail clean-authority publication; retain its exact
						// error.
						Files.writeString(directory.resolve("shutdown-failure.txt"), closeFailure.toString());
						if (!expectedForeignAuthorityFailure(closeFailure)
								|| !backing.valueStore().closedForDomainQualification()
								|| !backing.getTripleStore().closedForDomainQualification()) {
							throw closeFailure;
						}
					}
				}
				assertTrue(nativeSettled, "retain fresh fixture instead of closing a live native owner");
			} catch (Exception | Error cleanupFailure) {
				if (primaryFailure == null) {
					throw cleanupFailure;
				}
				if (cleanupFailure != primaryFailure) {
					primaryFailure.addSuppressed(cleanupFailure);
				}
			}
		}
	}

	@ParameterizedTest(name = "foreignOwner={0}")
	@ValueSource(strings = { "triples", "values" })
	void interruptedNativeAdmissionSettlesBothExactOwnersBeforeAnotherWriter(String environment,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CompletableFuture<Throwable> outcome = new CompletableFuture<>();
		AtomicBoolean interruptedAtReturn = new AtomicBoolean();
		Thread recovery = null;
		Process foreign = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			ProbeValues values = store.values.get();
			var vf = SimpleValueFactory.getInstance();
			var orphan = vf.createIRI("urn:retirement-held:orphan");
			values.startTransaction(true);
			long id = values.storeValue(orphan);
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			byte[] payload = values.getData(id).clone();
			LmdbSailStore backing = store.getBackingStore();
			foreign = startForeignWriter(directory, environment, "hold-abort");
			assertTrue(awaitFile(directory.resolve("foreign-admitted"), foreign),
					"the child must own the actual native writer before recovery starts");
			values.evidence = directory;
			values.armed.set(true);
			recovery = Thread.ofPlatform().name("interrupted-native-retirement").unstarted(() -> {
				values.recoveryOwner = Thread.currentThread();
				try {
					backing.recoverRetiredValueIds();
					outcome.complete(null);
				} catch (Throwable failure) {
					outcome.complete(failure);
				} finally {
					interruptedAtReturn.set(Thread.currentThread().isInterrupted());
				}
			});
			recovery.start();
			boolean waited = awaitNativeBeginOrCompletion(recovery, outcome);
			String waitingStack = java.util.Arrays.toString(recovery.getStackTrace());
			Files.writeString(directory.resolve("native-admission-stack.txt"), waitingStack);
			WriterTransaction tripleTicket = backing.getTripleStore().currentWriterTransaction();
			boolean dictionaryCommittedWhileForeignHeld = Files.exists(directory.resolve("dictionary-committed"));
			recovery.interrupt();
			Files.writeString(directory.resolve("release-foreign"), "abort the held native transaction\n");
			assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
			assertTrue(foreign.exitValue() == 0 && Files.exists(directory.resolve("foreign-aborted")));
			Throwable failure = outcome.get(20, TimeUnit.SECONDS);
			recovery.join(TimeUnit.SECONDS.toMillis(10));
			assertFalse(recovery.isAlive());
			assertNull(values.currentWriterTransaction());
			assertNull(backing.getTripleStore().currentWriterTransaction());
			long alias = values.getId(orphan);
			byte[] after = values.getData(id);
			var pending = values.pollRetiredIds(Long.MAX_VALUE, 64);
			try (var connection = repository.getConnection()) {
				connection.begin(org.eclipse.rdf4j.common.transaction.IsolationLevels.NONE);
				connection.add(vf.createIRI("urn:retirement-held:later"), vf.createIRI("urn:retirement-held:p"),
						vf.createIRI("urn:retirement-held:o"));
				connection.commit();
				assertEquals(1L, connection.size(), "a later independent writer must succeed after both owners settle");
			}
			assertAll(
					() -> assertTrue(waited, "recovery must wait for the real foreign native owner: " + waitingStack),
					() -> assertNotNull(tripleTicket, "the triple fence capability must precede either native wait"),
					() -> assertFalse(dictionaryCommittedWhileForeignHeld),
					() -> assertNotNull(failure,
							"interrupted admission must report failure after native ownership settles"),
					() -> assertTrue(interruptedAtReturn.get(), "the original native owner must retain interruption"),
					() -> assertEquals(id, alias, "an interrupted recovery must preserve the original alias"),
					() -> assertArrayEquals(payload, after),
					() -> assertTrue(pending != null && pending.ids.contains(id),
							"the original candidate must remain"));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				Files.writeString(directory.resolve("release-foreign"), "cleanup releases the native owner\n");
				if (foreign != null) {
					assertTrue(foreign.waitFor(20, TimeUnit.SECONDS), "retain fixture while a native child is live");
				}
				if (recovery != null) {
					recovery.join(TimeUnit.SECONDS.toMillis(20));
					assertFalse(recovery.isAlive(), "retain fixture while recovery owns a native handle");
				}
				LmdbSailStore backing = store.getBackingStore();
				assertTrue(backing == null || backing.valueStore().currentWriterTransaction() == null
						&& backing.getTripleStore().currentWriterTransaction() == null,
						"retain both environments if either native ticket survives");
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

	@ParameterizedTest(name = "foreignOwner={0}")
	@ValueSource(strings = { "triples", "values" })
	void foreignWriterWaitAllowsIndependentRead(String environment,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		CompletableFuture<Throwable> read = new CompletableFuture<>();
		Thread recovery = null;
		Thread reader = null;
		Process foreign = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			var vf = SimpleValueFactory.getInstance();
			var subject = vf.createIRI("urn:foreign-read:subject");
			var predicate = vf.createIRI("urn:foreign-read:predicate");
			var object = vf.createIRI("urn:foreign-read:object");
			try (var connection = repository.getConnection()) {
				connection.begin(org.eclipse.rdf4j.common.transaction.IsolationLevels.NONE);
				connection.add(subject, predicate, object);
				connection.commit();
			}
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			values.startTransaction(true);
			long id = values.storeValue(vf.createIRI("urn:foreign-read:orphan"));
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			foreign = startForeignWriter(directory, environment, "hold-abort");
			assertTrue(awaitFile(directory.resolve("foreign-admitted"), foreign));
			recovery = Thread.ofPlatform().name("foreign-read-recovery").start(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			assertTrue(awaitNativeBeginOrCompletion(recovery, recovered), "recovery must reach the held native writer");
			reader = Thread.ofPlatform().name("foreign-independent-reader").start(() -> {
				try (var connection = repository.getConnection()) {
					if (!connection.hasStatement(subject, predicate, object, false)) {
						throw new AssertionError("the independent read lost the live statement");
					}
					read.complete(null);
				} catch (Throwable failure) {
					read.complete(failure);
				}
			});
			assertTrue(awaitReadCompletionOrPublicationWait(reader, read));
			boolean readFinishedWhileHeld = read.isDone();
			Throwable readFailureWhileHeld = readFinishedWhileHeld ? read.getNow(null) : null;
			Files.writeString(directory.resolve("release-foreign"), "release after independent read observation\n");
			assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
			assertTrue(foreign.exitValue() == 0);
			recovered.get(20, TimeUnit.SECONDS);
			read.get(20, TimeUnit.SECONDS);
			assertAll(
					() -> assertTrue(readFinishedWhileHeld,
							"an unrelated read must finish while the foreign writer is held"),
					() -> assertNull(readFailureWhileHeld));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				Files.writeString(directory.resolve("release-foreign"), "cleanup releases foreign writer\n");
				if (foreign != null) {
					assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
				}
				for (Thread worker : new Thread[] { recovery, reader }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while an owner or shutdown is active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

