		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		CompletableFuture<Throwable> closed = new CompletableFuture<>();
		AtomicBoolean interruptAtReturn = new AtomicBoolean();
		Thread recovery = null;
		Thread shutdown = null;
		Process foreign = null;
		Throwable primary = null;
