			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			var vf = SimpleValueFactory.getInstance();
			var orphan = vf.createIRI("urn:overlay-rollback:orphan");
			var keeper = vf.createBNode("overlay-rollback-keeper");
			values.startTransaction(true);
			long keeperId = values.storeValue(keeper);
			long id = values.storeValue(orphan);
