	@Test
	void oldOverlayLeaseSurvivesRetirementAndLaterWriterUntilRebuild(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(true);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		var options = org.eclipse.rdf4j.sail.lmdb.valueoverlay.CompressedValueOverlay.Options.defaults(32L << 20);
		CountDownLatch writerStarted = new CountDownLatch(1);
		CountDownLatch releaseWriter = new CountDownLatch(1);
		AtomicReference<WriterTransaction> laterWriter = new AtomicReference<>();
		CompletableFuture<Throwable> decoded = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		CompletableFuture<Throwable> written = new CompletableFuture<>();
		Thread holder = null;
		Thread recovery = null;
		Thread writer = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			var vf = SimpleValueFactory.getInstance();
			var keeper = vf.createBNode("held-overlay-keeper");
			var orphan = vf.createIRI("urn:held-overlay:orphan");
			var later = values.createBNode("held-overlay-later");
			values.startTransaction(true);
			long keeperId = values.storeValue(keeper);
			long orphanId = values.storeValue(orphan);
			values.recordRetiredIds(List.of(orphanId), 0L);
			values.commit();
			assertTrue(values.awaitIndexRebuild(30, TimeUnit.SECONDS));
			values.warmCompressedValueOverlay(options);
			values.clearCaches();
			LmdbValue lazy = values.getLazyValue(keeperId);
			assertFalse(lazy.isInitialized());
			holder = Thread.ofPlatform().name("held-overlay-lease-reader").unstarted(() -> {
				try {
					lazy.getValueStoreRevision().resolveValues(new LmdbValue[] { lazy }, new int[] { 0 }, 1);
					decoded.complete(null);
				} catch (Throwable failure) {
					decoded.complete(failure);
				}
			});
			values.overlayLeaseOwner = holder;
			holder.start();
			assertTrue(values.overlayLeaseHeld.await(10, TimeUnit.SECONDS), "the real old overlay lease is held");
			var rolledBack = values.createBNode("held-overlay-rolled-back");
			var overlayBeforeRollback = values.compressedValueOverlayStats();
			assertNotNull(overlayBeforeRollback);
			values.startTransaction(true);
			values.storeValue(rolledBack);
			values.rollback();
			assertEquals(overlayBeforeRollback, values.compressedValueOverlayStats(),
					"rolling back a later writer must retain the overlay used by the old lease");
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(rolledBack));
			assertTrue(values.compressedValueOverlayRetainedMemoryStats().nativeBytes() > 0L);
			values.observeNativeCommit = true;
			recovery = Thread.ofPlatform().name("held-overlay-retirement").unstarted(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			values.recoveryOwner = recovery;
			recovery.start();
			assertTrue(values.nativeCommitReached.await(10, TimeUnit.SECONDS));
			assertTrue(awaitOverlayInvalidatedOrCompletion(values, recovered));
			assertNull(values.compressedValueOverlayStats(), "the new view must fall back to the dictionary");
			assertTrue(values.compressedValueOverlayRetainedMemoryStats().nativeBytes() > 0L,
					"the old leased overlay remains retained after invalidation");
			assertThrows(IllegalStateException.class, () -> values.warmCompressedValueOverlay(options),
					"warmup cannot certify a generation before the deferred reset");
			writer = Thread.ofPlatform().name("held-overlay-later-writer").start(() -> {
				try {
					values.startTransaction(true);
					values.storeValue(later);
					laterWriter.set(values.currentWriterTransaction());
					writerStarted.countDown();
					if (!releaseWriter.await(30, TimeUnit.SECONDS)) {
						throw new IOException("fixture did not release later writer");
					}
					values.commit();
					written.complete(null);
				} catch (Throwable failure) {
					written.complete(failure);
				}
			});
			assertTrue(writerStarted.await(10, TimeUnit.SECONDS), "a later writer must start while reset waits");
			values.releaseOverlayLease.countDown();
			assertNull(decoded.get(20, TimeUnit.SECONDS));
			boolean reachedNextAdmission = awaitRetirementWriterWait(recovery, recovered);
			if (!reachedNextAdmission) {
				Files.writeString(directory.resolve("overlay-recovery-wait-stack.txt"),
						"recovery " + recovery.getState() + " " + java.util.Arrays.toString(recovery.getStackTrace())
								+ "\nwriter " + writer.getState() + " "
								+ java.util.Arrays.toString(writer.getStackTrace()));
			}
			assertTrue(reachedNextAdmission,
					"the old reset must finish before the next batch waits for the later dictionary writer");
			assertEquals(keeper.stringValue(), lazy.stringValue(), "the held old overlay must still decode its value");
			assertSame(laterWriter.get(), values.currentWriterTransaction(),
					"old reset must not consume the later writer");
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(later), "uncommitted later identity must remain hidden");
			releaseWriter.countDown();
			assertNull(written.get(20, TimeUnit.SECONDS));
			assertNull(recovered.get(20, TimeUnit.SECONDS));
			values.warmCompressedValueOverlay(options);
			assertNotNull(values.compressedValueOverlayStats());
			assertTrue(values.getId(later) != LmdbValue.UNKNOWN_ID);
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan));
			assertEquals(keeper, values.getValue(keeperId));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				ProbeValues values = store.values.get();
				if (values != null) {
					values.releaseOverlayLease.countDown();
				}
				releaseWriter.countDown();
				for (Thread worker : new Thread[] { holder, recovery, writer }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while a native or overlay owner remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

	@Test
	void overlayWarmPublicationCannotWaitForTheRetirementIdentityGate(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(true);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		var options = org.eclipse.rdf4j.sail.lmdb.valueoverlay.CompressedValueOverlay.Options.defaults(32L << 20);
		CountDownLatch registryHeld = new CountDownLatch(1);
		CountDownLatch releaseWarm = new CountDownLatch(1);
		CountDownLatch scopeResolved = new CountDownLatch(1);
		AtomicBoolean intercept = new AtomicBoolean(true);
		CompletableFuture<Throwable> warmed = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		Thread warmer = null;
		Thread recovery = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			var vf = SimpleValueFactory.getInstance();
			var orphan = vf.createIRI("urn:overlay-retirement:orphan");
			var keeper = vf.createIRI("urn:overlay-retirement:keeper");
			values.startTransaction(true);
			values.storeValue(keeper);
			long id = values.storeValue(orphan);
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			assertTrue(values.awaitIndexRebuild(30, TimeUnit.SECONDS));
			values.warmCompressedValueOverlay(options);
			warmer = Thread.ofPlatform().name("overlay-publication-holder").start(() -> {
				try {
					values.warmCompressedValueOverlay(options, () -> {
						boolean inPublication = java.util.Arrays.stream(Thread.currentThread().getStackTrace())
								.anyMatch(frame -> frame.getClassName()
										.equals(
												"org.eclipse.rdf4j.sail.lmdb.valueoverlay.ValueOverlayRegistry")
										&& frame.getMethodName().equals("publish"));
						if (inPublication && intercept.compareAndSet(true, false)) {
							registryHeld.countDown();
							try {
								if (!releaseWarm.await(30, TimeUnit.SECONDS)) {
									throw new AssertionError("fixture did not release overlay publication");
								}
								try (var scope = values.openValueResolutionScope()) {
									scopeResolved.countDown();
								}
							} catch (InterruptedException interrupted) {
								Thread.currentThread().interrupt();
								return true;
							} catch (org.eclipse.rdf4j.sail.SailException interruptedScope) {
								if (!Thread.currentThread().isInterrupted()) {
									throw interruptedScope;
								}
								return true;
							}
						}
						return false;
					});
					warmed.complete(null);
				} catch (Throwable failure) {
					warmed.complete(failure);
				}
			});
			assertTrue(registryHeld.await(10, TimeUnit.SECONDS), "warm publication must own the real registry monitor");
			recovery = Thread.ofPlatform().name("overlay-retirement-owner").start(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			assertTrue(awaitOverlayRegistryWaitOrCompletion(recovery, recovered));
			WriterTransaction statementWriter = backing.getTripleStore().currentWriterTransaction();
			WriterTransaction dictionaryWriter = values.currentWriterTransaction();
			releaseWarm.countDown();
			assertTrue(awaitScopeAdmissionOrWait(warmer, scopeResolved, warmed));
			boolean independentScopeCompleted = scopeResolved.getCount() == 0;
			if (!independentScopeCompleted && !warmed.isDone()) {
				warmer.interrupt();
			}
			Throwable warmFailure = warmed.get(20, TimeUnit.SECONDS);
			Throwable recoveryFailure = recovered.get(20, TimeUnit.SECONDS);
			assertAll(
					() -> assertNull(statementWriter, "overlay publication wait cannot retain the statement writer"),
					() -> assertNull(dictionaryWriter, "overlay publication wait cannot retain the dictionary writer"),
					() -> assertTrue(independentScopeCompleted, "overlay publication must acquire the identity scope"),
					() -> assertNull(warmFailure),
					() -> assertNull(recoveryFailure),
					() -> assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan)),
					() -> assertTrue(values.getId(keeper) != LmdbValue.UNKNOWN_ID));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				releaseWarm.countDown();
				if (warmer != null && warmer.isAlive()) {
					warmer.interrupt();
				}
				for (Thread worker : new Thread[] { warmer, recovery }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while overlay or retirement remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

	@Test
	void occupiedIdentityGateAbortsTheUnpublishedNativeWriterOnItsOwner(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CountDownLatch gateHeld = new CountDownLatch(1);
		CountDownLatch releaseGate = new CountDownLatch(1);
		CompletableFuture<Throwable> reader = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		AtomicReference<Thread> readerOwner = new AtomicReference<>();
		Thread recovery = null;
		Thread readerThread = null;
		Process foreign = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			var vf = SimpleValueFactory.getInstance();
			var orphan = vf.createIRI("urn:unpublished-retirement:orphan");
			values.startTransaction(true);
			long id = values.storeValue(orphan);
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			values.pauseBeforeRetirementPublication.set(true);
			recovery = Thread.ofPlatform().name("unpublished-retirement-owner").unstarted(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			values.recoveryOwner = recovery;
			recovery.start();
			assertTrue(values.retirementNativeBegun.await(10, TimeUnit.SECONDS));
			values.getTxnManager().setAdmissionObserverForTest(transaction -> {
				if (Thread.currentThread() == readerOwner.get()) {
					gateHeld.countDown();
					try {
						if (!releaseGate.await(30, TimeUnit.SECONDS)) {
							throw new AssertionError("fixture did not release identity reader");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new AssertionError(interrupted);
					}
				}
			});
			readerThread = Thread.ofPlatform().name("unpublished-retirement-reader").unstarted(() -> {
				try {
					values.getId(vf.createIRI("urn:unpublished-retirement:missing"));
					reader.complete(null);
				} catch (Throwable failure) {
					reader.complete(failure);
				}
			});
			readerOwner.set(readerThread);
			readerThread.start();
			assertTrue(gateHeld.await(10, TimeUnit.SECONDS), "reader must own the real identity gate");
			values.releaseRetirementPublication.countDown();
			assertTrue(awaitNativeOwnersReleased(backing, recovered));
			assertTrue(awaitAssociationWaitOrCompletion(recovery, recovered));
			assertNull(values.currentWriterTransaction());
			assertNull(backing.getTripleStore().currentWriterTransaction());
			foreign = startForeignWriter(directory, "values", "hold-abort");
			assertTrue(awaitFile(directory.resolve("foreign-admitted"), foreign),
					"an independent process must acquire the native writer after the unpublished abort");
			Files.writeString(directory.resolve("release-foreign"), "release after observed native abort\n");
			assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
			assertEquals(0, foreign.exitValue());
			releaseGate.countDown();
			assertNull(reader.get(20, TimeUnit.SECONDS));
			assertNull(recovered.get(20, TimeUnit.SECONDS));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				ProbeValues values = store.values.get();
				if (values != null) {
					values.releaseRetirementPublication.countDown();
					values.getTxnManager().setAdmissionObserverForTest(null);
				}
				releaseGate.countDown();
				Files.writeString(directory.resolve("release-foreign"), "cleanup releases foreign writer\n");
				if (foreign != null) {
					assertTrue(foreign.waitFor(20, TimeUnit.SECONDS));
				}
				for (Thread worker : new Thread[] { readerThread, recovery }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while an owner remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

