			recovery.start();
			assertTrue(values.livenessComplete.await(10, TimeUnit.SECONDS));
			holder = Thread.ofPlatform().name("association-retirement-reader").unstarted(() -> {
				try (var scope = values.openValueResolutionScope()) {
					held.complete(null);
				} catch (Throwable failure) {
					held.complete(failure);
				}
			});
			values.scopeOwner = holder;
			holder.start();
			assertTrue(awaitScopeAdmissionOrWait(holder, values.scopeAdmissionHeld, held));
			boolean readerEnteredGate = values.scopeAdmissionHeld.getCount() == 0;
			values.releaseLiveness.countDown();
