	@Test
	void interruptedDictionaryResetRetainsDurableRetirementReceipt(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CompletableFuture<Throwable> held = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		AtomicBoolean interruptedOnReturn = new AtomicBoolean();
		Thread holder = null;
		Thread recovery = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			var orphan = SimpleValueFactory.getInstance().createIRI("urn:interrupted-reset:orphan");
			values.startTransaction(true);
			long id = values.storeValue(orphan);
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			long generationBefore = values.nativeCommitGeneration();
			holder = Thread.ofPlatform().name("interrupted-reset-dictionary-reader").unstarted(() -> {
				try {
					values.occupiedBytes();
					held.complete(null);
				} catch (Throwable failure) {
					held.complete(failure);
				}
			});
			values.metadataOwner = holder;
			holder.start();
			assertTrue(values.metadataBarrierHeld.await(10, TimeUnit.SECONDS));
			values.observeNativeCommit = true;
			recovery = Thread.ofPlatform().name("interrupted-reset-retirement").unstarted(() -> {
				Throwable failure = null;
				try {
					backing.recoverRetiredValueIds();
				} catch (Throwable caught) {
					failure = caught;
				} finally {
					interruptedOnReturn.set(Thread.currentThread().isInterrupted());
					recovered.complete(failure);
				}
			});
			values.recoveryOwner = recovery;
			recovery.start();
			assertTrue(values.nativeCommitReached.await(10, TimeUnit.SECONDS));
			assertTrue(awaitDictionaryResetOrCompletion(recovery, recovered));
			recovery.interrupt();
			Throwable failure = recovered.get(20, TimeUnit.SECONDS);
			boolean nativeCommitted = values.lastNativeCommitSucceeded();
			long generationAfter = values.nativeCommitGeneration();
			WriterTransaction statementWriter = backing.getTripleStore().currentWriterTransaction();
			WriterTransaction dictionaryWriter = values.currentWriterTransaction();
			values.releaseMetadataBarrier.countDown();
			assertNull(held.get(20, TimeUnit.SECONDS));
			var remaining = values.pollRetiredIds(Long.MAX_VALUE, 64);
			assertAll(
					() -> assertNotNull(failure, "interrupted reset must propagate its failure"),
					() -> assertTrue(interruptedOnReturn.get(), "reset interruption must remain visible to its owner"),
					() -> assertTrue(nativeCommitted,
							"the already committed dictionary receipt must survive reset failure"),
					() -> assertTrue(generationAfter > generationBefore, "the durable native generation must advance"),
					() -> assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan)),
					() -> assertTrue(remaining == null || !remaining.ids.contains(id),
							"a completed native commit must not restore its consumed retirement record"),
					() -> assertNull(statementWriter),
					() -> assertNull(dictionaryWriter));
			values.startTransaction(true);
			values.storeValue(SimpleValueFactory.getInstance().createIRI("urn:interrupted-reset:later"));
			values.rollback();
			assertNull(values.currentWriterTransaction());
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				ProbeValues values = store.values.get();
				if (values != null) {
					values.releaseMetadataBarrier.countDown();
				}
				for (Thread worker : new Thread[] { holder, recovery }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while a native owner remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

