	@Test
	void publicationGateHeldByReaderReleasesNativeOwnersBeforeWaiting(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CountDownLatch gateHeld = new CountDownLatch(1);
		CountDownLatch releaseGate = new CountDownLatch(1);
		CountDownLatch nativeWritersStarted = new CountDownLatch(1);
		CompletableFuture<Throwable> read = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		AtomicReference<Thread> readerOwner = new AtomicReference<>();
		Thread reader = null;
		Thread recovery = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			values.startTransaction(true);
			long id = values.storeValue(SimpleValueFactory.getInstance().createIRI("urn:held-publication:orphan"));
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			TxnManager statements = backing.getTripleStore().getTxnManager();
			TxnManager dictionary = values.getTxnManager();
			statements.setAdmissionObserverForTest(transaction -> {
				if (Thread.currentThread() == readerOwner.get()) {
					gateHeld.countDown();
					try {
						if (!releaseGate.await(30, TimeUnit.SECONDS)) {
							throw new AssertionError("fixture did not release the reader's publication gate");
						}
					} catch (InterruptedException failure) {
						Thread.currentThread().interrupt();
						throw new AssertionError(failure);
					}
				}
			});
			reader = Thread.ofPlatform().name("held-publication-reader").unstarted(() -> {
				try (var ignored = backing.beginDatasetAdmission(
						org.eclipse.rdf4j.common.transaction.IsolationLevels.SNAPSHOT_READ, null)) {
					read.complete(null);
				} catch (Throwable failure) {
					read.complete(failure);
				}
			});
			readerOwner.set(reader);
			reader.start();
			assertTrue(gateHeld.await(10, TimeUnit.SECONDS), "the real reader must hold publication admission");
			int statementPermits = statements.availableOrdinaryPermits();
			int dictionaryPermits = dictionary.availableOrdinaryPermits();
			values.retirementStarted = nativeWritersStarted;
			recovery = Thread.ofPlatform().name("held-publication-recovery").unstarted(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			values.recoveryOwner = recovery;
			recovery.start();
			boolean admittedBeforeGate = nativeWritersStarted.await(10, TimeUnit.SECONDS);
			boolean releasedBeforeWait = admittedBeforeGate && awaitNativeOwnersReleased(backing, recovered);
			int statementsWhileHeld = statements.availableOrdinaryPermits();
			int dictionaryWhileHeld = dictionary.availableOrdinaryPermits();
			releaseGate.countDown();
			Throwable readFailure = read.get(20, TimeUnit.SECONDS);
			Throwable recoveryFailure = recovered.get(20, TimeUnit.SECONDS);
			assertAll(
					() -> assertTrue(admittedBeforeGate,
							"native admission must precede the nonblocking publication try"),
					() -> assertTrue(releasedBeforeWait, "both native owners must settle before the gate wait"),
					() -> assertEquals(statementPermits, statementsWhileHeld),
					() -> assertEquals(dictionaryPermits, dictionaryWhileHeld),
					() -> assertNull(readFailure),
					() -> assertNull(recoveryFailure));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				releaseGate.countDown();
				LmdbSailStore backing = store.getBackingStore();
				if (backing != null) {
					backing.getTripleStore().getTxnManager().setAdmissionObserverForTest(null);
				}
				for (Thread worker : new Thread[] { reader, recovery }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while a native owner remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

	@Test
	void dictionaryOnlyOwnerCanFinishItsTripleWorkBeforeRetirementRetries(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true)
				.setInlineLiterals(false)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		ProbeStore store = new ProbeStore(directory, config);
		SailRepository repository = new SailRepository(store);
		CountDownLatch dictionaryHeld = new CountDownLatch(1);
		CountDownLatch releaseDictionary = new CountDownLatch(1);
		CompletableFuture<Throwable> ownerDone = new CompletableFuture<>();
		CompletableFuture<Throwable> tripleDone = new CompletableFuture<>();
		CompletableFuture<Throwable> recovered = new CompletableFuture<>();
		Thread owner = null;
		Thread tripleWorker = null;
		Thread recovery = null;
		Throwable primary = null;
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			ProbeValues values = store.values.get();
			values.startTransaction(true);
			long id = values.storeValue(SimpleValueFactory.getInstance().createIRI("urn:term-owner:orphan"));
			values.recordRetiredIds(List.of(id), 0L);
			values.commit();
			owner = Thread.ofPlatform().name("dictionary-only-owner").start(() -> {
				try {
					values.startTransaction(true);
					dictionaryHeld.countDown();
					if (!releaseDictionary.await(30, TimeUnit.SECONDS)) {
						throw new IOException("Fixture did not allow the dictionary owner to proceed");
					}
					values.rollback();
					ownerDone.complete(null);
				} catch (Throwable failure) {
					try {
						values.rollback();
					} catch (Throwable cleanup) {
						if (failure != cleanup) {
							failure.addSuppressed(cleanup);
						}
					}
					ownerDone.complete(failure);
				}
			});
			assertTrue(dictionaryHeld.await(10, TimeUnit.SECONDS));
			recovery = Thread.ofPlatform().name("term-owner-retirement").start(() -> {
				try {
					backing.recoverRetiredValueIds();
					recovered.complete(null);
				} catch (Throwable failure) {
					recovered.complete(failure);
				}
			});
			assertTrue(awaitDictionaryWaitOrCompletion(recovery, recovered));
			boolean pendingWhileHeld = !recovered.isDone();
			tripleWorker = Thread.ofPlatform().name("dictionary-owner-triple-work").start(() -> {
				WriterTransaction tripleTicket = new WriterTransaction();
				try {
					TripleStore triples = backing.getTripleStore();
					triples.startTransaction(triples.prepareReplayDecision(), tripleTicket);
					triples.rollback(tripleTicket);
					tripleDone.complete(null);
				} catch (Throwable failure) {
					try {
						backing.getTripleStore().rollback(tripleTicket);
					} catch (Throwable cleanup) {
						if (failure != cleanup) {
							failure.addSuppressed(cleanup);
						}
					}
					tripleDone.complete(failure);
				}
			});
			boolean tripleFinishedWithoutRelease;
			try {
				tripleDone.get(10, TimeUnit.SECONDS);
				tripleFinishedWithoutRelease = true;
			} catch (java.util.concurrent.TimeoutException blocked) {
				tripleFinishedWithoutRelease = false;
			}
			releaseDictionary.countDown();
			boolean tripleFinished = tripleFinishedWithoutRelease;
			Throwable tripleFailure = tripleDone.get(20, TimeUnit.SECONDS);
			Throwable ownerFailure = ownerDone.get(20, TimeUnit.SECONDS);
			Throwable recoveryFailure = recovered.get(20, TimeUnit.SECONDS);
			assertAll(
					() -> assertTrue(pendingWhileHeld, "retirement must wait and retry behind the dictionary owner"),
					() -> assertTrue(tripleFinished,
							"the dictionary owner must acquire and release the native triple writer without a cycle"),
					() -> assertNull(tripleFailure),
					() -> assertNull(ownerFailure),
					() -> assertNull(recoveryFailure),
					() -> assertNull(values.currentWriterTransaction()),
					() -> assertNull(backing.getTripleStore().currentWriterTransaction()));
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			try {
				releaseDictionary.countDown();
				if (recovery != null) {
					recovery.interrupt();
				}
				for (Thread worker : new Thread[] { recovery, owner, tripleWorker }) {
					if (worker != null) {
						worker.join(TimeUnit.SECONDS.toMillis(20));
						assertFalse(worker.isAlive(), "retain fixture while a native owner remains active");
					}
				}
				repository.shutDown();
			} catch (Exception | Error cleanup) {
				if (primary == null) {
					throw cleanup;
				}
				if (primary != cleanup) {
					primary.addSuppressed(cleanup);
				}
			}
		}
	}

